// 1. Get the current history array from memory, or start a blank one if it doesn't exist
var history = context.get('sound_history') || [];

// 2. Add the newest time-stamped message to the FRONT of the list
history.unshift(msg.payload);

// 3. If the list is longer than 5 items, chop off the oldest ones
if (history.length > 5) {
    history = history.slice(0, 5);
}

// 4. Save the updated list back into memory
context.set('sound_history', history);

// 5. Join the 5 items together with a new line (\n) so they stack neatly in the text box
msg.payload = history.join('\n');

return msg;

// Retrieve the existing log array from memory, or start a new empty one
var logs = context.get('occupancyLogs') || [];

// Create a new log entry timestamped right now
var now = new Date();
var timestamp = now.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) +
    ' ' +
    now.toLocaleTimeString('en-US', { hour12: false });

var incoming = msg.payload;
var isOccupied = false;

// Update status indicator on canvas for easy debugging
var debugText = typeof incoming === 'object' ? JSON.stringify(incoming) : String(incoming);
node.status({ fill: "blue", shape: "dot", text: "Received: " + debugText });

// --- THE FIXED EXTENDED LOGIC ---
if (incoming === 1 || incoming === "1" || incoming === true) {
    // Matches raw number 1, string "1", or boolean true
    isOccupied = true;
} else if (typeof incoming === 'string' && (incoming.toLowerCase() === 'occupied' || incoming.toLowerCase() === 'occupy')) {
    // Matches text strings like "Occupied", "occupied", "OCCUPIED"
    isOccupied = true;
} else if (incoming && typeof incoming === 'object' && (incoming.prediction === 'Occupied' || incoming.payload === 'Occupied')) {
    // Fallback if the ML node sends a nested JSON object
    isOccupied = true;
}

var currentStatus = isOccupied ? "Vacant" : "Occupied";
var statusClass = isOccupied ? "log-vacant" : "log-occupied";

var newEntry = {
    time: timestamp,
    status: currentStatus,
    class: statusClass
};

// Add the new log to the TOP of the list
logs.unshift(newEntry);

// Limit the array size to 150 entries to keep it light
if (logs.length > 150) {
    logs = logs.slice(0, 150);
}

// Save the updated list back into context memory
context.set('occupancyLogs', logs);

// Pass the array along to the UI Template
msg.payload = logs;
return msg;
